def run(ds):
 import numpy as np
 validate();gt_guard();start=time.perf_counter();aud=read(D/ds/'reporting_receipt.json');assert aud['status']=='verified_whole_domain_geometric_controls_arrays_parent_SHA_inherited_baselines_and_all_means';assert aud['metrics_sha256']==sha(D/ds/'metrics.json')and aud['score_sha256']==sha(D/ds/'score_receipt.json');rr=read(D/ds/'metrics.json')['private_rows'];rep=read(P/ds/'report.json');assert len(rr)==COUNTS[ds];tails={}
 for a,b in PAIRS:
  dt=np.asarray([100*(r['values'][a]['t']-r['values'][b]['t'])for r in rr]);dv=np.asarray([100*(r['values'][a]['v']-r['values'][b]['v'])for r in rr]);tails[a+'-'+b]=dict(severe_t=int((dt< -5).sum()),severe_v=int((dv< -5).sum()),severe_union_once=int(((dt< -5)|(dv< -5)).sum()),rescue_union_once=int(((dt>5)|(dv>5)).sum()),v_improve=int((dv>0).sum()),v_harm=int((dv<0).sum()),v_tie=int((dv==0).sum()))
 for arm,m in rep['means'].items():
  for k,v in m.items():
   x=[r['values'][arm][k]for r in rr if r['values'][arm][k]is not None];assert(v is None and not x)or abs(v-float(np.mean(x)))<1e-12
 seal=read(D/ds/'sealed.json');changed={k:sum(e['provenance'][k]>0 for e in seal['files'].values())for k in ['clipped_frames','fallback_frames']};framecounts={k:sum(e['provenance'][k]for e in seal['files'].values())for k in changed};out=P/ds;atomic(out/'root_all_paired_tails_v1.json',tails);text=f'# {ds}: whole-target fixed-time geometry safety controls\n\nAll{COUNTS[ds]} current full queries sealed before official new-arm scores, separate exact all-array/parent SHA/mean audit passed. These are descriptive posthoc review controls after original target results were exposed, not unseen parameter selection or a production change.\n\n|Arm|tIoU %|vIoU %|R.3 %|R.5 %|\n|---|---:|---:|---:|---:|\n'
 for a,m in rep['means'].items():text+=f'|{a}|{100*m["t"]:.6f}|{100*m["v"]:.6f}|{100*m["vIoU_ge_03"]:.6f}|{100*m["vIoU_ge_05"]:.6f}|\n'
 text+='\nParent-paired10000 bootstrap pointwise95%CI:\n\n'
