 for group,g in rep['timegroups'].items():
  for k,z in g['paired'].items():text+=f'- {group}, n{g["queries"]}, {k}: v{z["v"]["mean"]:+.6f} CI{z["v"]["CI95"]}.\n'
 text+=f'\nGeometrically modified queries across allnativeframes: {changed}; modified frame counts {framecounts}. Clipping uses only the image rectangle. Fully-outside fallback uses original Source box iff original Full has zero image intersection/nonpositive size. Current event remains unchanged. Source fallback keeps every unselected box bitwise unchanged; ClipToImage explicitly roundtrips all boxes through xyxy and can introduce ULP changes even for in-image boxes (independent magnitude diagnostics retained), so these controls cannot repair wrong temporal boundaries. Current original trajectories remain immutable and unclipped in the original result. No low-IoU/GT/identity rule or score-selected threshold. The two controls are fully reported and no new default is selected. Partial crossing, fully off-image, identity switches and occlusion are distinct; only the first two are exactly measured here.\n\nNo model/Source/expert/optimizer calls; Source/Full metrics inherited only with exact original complete-array/SHA/audit lineage. New two-arm official scores and independent array audit are separate processes. Conditional replay/official/audit wall clocks include IO/checks and are not complete deployment speed; original Source/eight-expert acquisitions remain nonzero. All signed negatives, severe tails/rescues and short/long strata retained.\n'
 (out/'ROOT_FINDINGS_v2.md').write_text(text);rec=dict(status='root_whole_geometry_controls_all_signed_tails_shortlong_cost_analysis_complete',audit_sha256=sha(D/ds/'reporting_receipt.json'),findings_sha256=sha(out/'ROOT_FINDINGS_v2.md'),code_sha256=sha(Path(__file__)),worker=identity(),elapsed_root_seconds=time.perf_counter()-start,conditional_predict_seconds=seal['elapsed_wall_seconds'],official_score=read(D/ds/'score_receipt.json'),independent_audit=aud,new_model=0,new_Source=0,new_expert=0,new_GT_scoring=0);atomic(out/'root_cost_and_analysis_receipt_v2.json',rec);atomic(D/ds/'root_export_receipt_v2.json',rec)
